// The reading list: the books, NASA monographs, standards, handbooks and libraries behind this site. For each one,
// what it covers, why it is worth your time, where to get it, and which pages of this site cite it (found in the page
// text at build time, from the `find` patterns). Reading paths put a few of them in order for one kind of work.
// Scope as the rest of the site: hardware, structures, materials, process and inspection. Propellant formulation,
// energetics and initiation are outside it.

export type Kind = 'book' | 'mono' | 'std' | 'hdbk' | 'report' | 'paper' | 'data' | 'site';
export const KINDS: Record<Kind, string> = {
  book: 'Book', mono: 'NASA monograph', std: 'Standard', hdbk: 'Handbook', report: 'Report', paper: 'Paper', data: 'Database', site: 'Library',
};

export const CATS: { key: string; name: string; d: string }[] = [
  { key: 'srm', name: 'Solid rocket motors', d: 'The motor as a whole, and the NASA design monographs on its parts. Most of the monographs are free on NTRS.' },
  { key: 'struct', name: 'Structures and stability', d: 'Hand methods, stability, stress concentration and finite elements.' },
  { key: 'mat', name: 'Materials and allowables', d: 'Where design values come from, and how to select a material.' },
  { key: 'life', name: 'Fracture, fatigue and life', d: 'Cracks, cycles, and the fracture control of pressure vessels.' },
  { key: 'poly', name: 'Polymers, seals and adhesives', d: 'Viscoelasticity, rubber, O-rings and bonded joints.' },
  { key: 'machine', name: 'Machine design and fasteners', d: 'Preload, joint diagrams, threads and fastener requirements.' },
  { key: 'make', name: 'Making and inspecting', d: 'Welding, manufacturability, additive manufacturing and NDT.' },
  { key: 'draw', name: 'Drawing and tolerancing', d: 'The standards and the texts behind a drawing.' },
  { key: 'sys', name: 'Requirements, loads and verification', d: 'Systems engineering, environments, models and tests.' },
  { key: 'where', name: 'Where to look things up', d: 'Libraries and databases to bookmark, not to read from cover to cover.' },
];

export interface Source {
  id: string; cat: string; kind: Kind;
  title: string; who: string; pub: string; // authors or body; edition, publisher and year
  free: boolean; start?: boolean;
  get: string; url?: string; // where to get it; an official page for the free ones
  what: string; why: string;
  find: string[]; // regular expressions that find a citation in the text of a page
}

const NTRS = (q: string) => `https://ntrs.nasa.gov/search?q=${encodeURIComponent(q)}`;
const NASA_STD = 'https://standards.nasa.gov';
const ASSIST = 'https://quicksearch.dla.mil';

